/**
 * FA-1.81 (tj D3) — v1's offer JSON-LD must not change when the builder is shared with v2.
 *
 * `ExperienceV1` runs unmodified against a fake service client that serves the two fixtures in
 * v1-offer-jsonld-fixtures.ts; the `<script type="application/ld+json">` payloads are read out of
 * the element tree it returns and compared, byte for byte, with the golden file. The golden was
 * produced once by running this same harness against the code on `main` BEFORE the refactor —
 * it is never regenerated by a test run, and `git diff main -- __golden__/` must stay empty.
 *
 * Only the component's own body runs (the tree is walked, not rendered), so no client component,
 * map or image loader is involved.
 */

import { describe, it, expect, vi } from 'vitest'
import type { ReactElement, ReactNode } from 'react'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { V1_FULL, V1_REQUEST, type V1Fixture } from './v1-offer-jsonld-fixtures'

const h = vi.hoisted(() => ({ fixture: null as unknown as V1Fixture }))

vi.mock('next/navigation', () => ({ notFound: () => { throw new Error('NEXT_NOT_FOUND') } }))
vi.mock('@/components/layout/nav', () => ({ SiteNav: () => null }))
vi.mock('@/components/layout/footer', () => ({ SiteFooter: () => null }))
vi.mock('@/app/trips/exp-page-map-wrapper', () => ({ default: () => null }))

vi.mock('@/lib/supabase/server', () => {
  /** A chainable, awaitable query: `.single()` returns the fixture row, a bare `await` returns []. */
  function from(table: string) {
    const chain: Record<string, unknown> = {}
    for (const m of ['select', 'eq', 'neq', 'gte', 'lte', 'in', 'is', 'order', 'limit']) chain[m] = () => chain
    chain.single = async () => ({
      data: table === 'experience_pages' ? h.fixture.page : table === 'guides' ? h.fixture.guide : null,
      error: null,
    })
    chain.then = (resolve: (v: unknown) => unknown) => Promise.resolve({ data: [], error: null }).then(resolve)
    return chain
  }
  return { createServiceClient: () => ({ from }), createClient: async () => ({ from }) }
})

import ExperienceV1 from '../_v1/ExperienceV1'

/** Every `<script type="application/ld+json">` payload in the element tree, in document order. */
function ldJson(node: ReactNode): string[] {
  if (node == null || typeof node !== 'object') return []
  if (Array.isArray(node)) return node.flatMap(ldJson)
  const el = node as ReactElement<{ type?: string; children?: ReactNode; dangerouslySetInnerHTML?: { __html: string } }>
  if (el.type === 'script' && el.props.type === 'application/ld+json') return [el.props.dangerouslySetInnerHTML?.__html ?? '']
  return ldJson(el.props?.children)
}

async function emitted(fixture: V1Fixture): Promise<string[]> {
  h.fixture = fixture
  return ldJson(await ExperienceV1({ slug: fixture.slug }))
}

const golden = JSON.parse(readFileSync(join(__dirname, '__golden__', 'v1-offer-jsonld.json'), 'utf-8')) as {
  full: unknown[]
  request: unknown[]
}

// The golden stores each payload parsed and pretty-printed; JSON.stringify(JSON.parse(s)) === s for
// anything JSON.stringify produced, so comparing re-serialised golden to the emitted string is byte equality.
const asEmitted = (payloads: unknown[]) => payloads.map(p => JSON.stringify(p))

describe('v1 offer JSON-LD is unchanged (golden fixture)', () => {
  it('page with FAQ, location, season, price and guide → TouristTrip, BreadcrumbList, FAQPage — byte-identical', async () => {
    expect(await emitted(V1_FULL)).toEqual(asEmitted(golden.full))
  })

  it('price on request, no FAQ, no location, no guide → TouristTrip without offers, BreadcrumbList — byte-identical', async () => {
    expect(await emitted(V1_REQUEST)).toEqual(asEmitted(golden.request))
  })
})
